def solve(env, goal):
    import re
    from collections import deque

    def parse_obs(obs):
        items = []
        for m in re.finditer(r'\ba ([a-z]+) (\d+)\b', obs):
            items.append((m.group(1), m.group(2)))
        return items

    # parse goal
    parts = goal.split()
    obj_type = None
    target_type = None
    for i, w in enumerate(parts):
        if w in ('in', 'on'):
            obj_type = parts[i - 1]
            j = i + 1
            while j < len(parts) and parts[j] == 'the':
                j += 1
            target_type = parts[j]
            break
    if obj_type is None:
        m = re.search(r'put a (\w+) (?:in|on) (\w+)', goal, re.IGNORECASE)
        if m:
            obj_type = m.group(1)
            target_type = m.group(2)

    CONTAINERS = {'drawer', 'cabinet', 'fridge', 'microwave', 'safe', 'cupboard'}

    obs = env.observation
    items = parse_obs(obs)

    target_loc = None
    for typ, num in items:
        if typ == target_type:
            target_loc = f"{typ} {num}"
            break

    obj_name = None
    visited = set()
    for typ, num in items:
        loc = f"{typ} {num}"
        if loc in visited:
            continue
        visited.add(loc)

        env.step(f"go to {loc}")
        obs = env.observation
        items_here = parse_obs(obs)

        for t2, n2 in items_here:
            if t2 == obj_type:
                env.step(f"take {t2} {n2} from {loc}")
                obj_name = f"{t2} {n2}"
                break
        if obj_name is not None:
            break

        if typ in CONTAINERS:
            env.step(f"open {loc}")
            obs = env.observation
            items_here = parse_obs(obs)
            for t2, n2 in items_here:
                if t2 == obj_type:
                    env.step(f"take {t2} {n2} from {loc}")
                    obj_name = f"{t2} {n2}"
                    break
            if obj_name is not None:
                break

    if obj_name is None:
        return

    if target_loc:
        env.step(f"go to {target_loc}")
        typ = target_loc.split()[0]
        if typ in CONTAINERS:
            env.step(f"open {target_loc}")
        env.step(f"move {obj_name} to {target_loc}")
